// 作者意图只有真实活跃Director策略可提交；原Grant和本人答受仍在原业务writer重核。
#include "political_governance_agency_intent_world.hpp"
#include "world_bundle.hpp"
namespace hanmo::resident {namespace {
// 同候选查原登记的具名策略；模板预算不能变成公权，玩家更不能伪装NPC来源。
Outcome<StableId> policy_id(const WorldBundle& w,const StableId& actor){if(!w.catalog->director||!w.catalog->director->governance_agency_intents||!w.catalog->political_governance_agencies||w.catalog->political_governance_agencies->version!=2||actor==w.common.state().metadata.player_actor_id)return {false,{},common_failure("GovernanceAgencyIntentProfileRequired",actor).error};const auto* policy=director_policy(w.director,*w.catalog->director,actor);if(!policy||!director_subject_active(w.director,actor)||!policy->governance_agency_intent_id||std::find(policy->templates.begin(),policy->templates.end(),DirectorTemplate::governance_agency)==policy->templates.end())return {false,{},common_failure("GovernanceAgencyIntentDirectorPolicyMismatch",actor).error};if(w.catalog->director->dynamic_subjects){const auto* r=w.director.registrations.find(actor);if(!r||r->obligations_only)return {false,{},common_failure("GovernanceAgencyIntentDirectorPolicyMismatch",actor).error};return {true,r->policy_id,{}};}return {true,actor,{}};}
Status guard(const WorldBundle& w,const StableId& actor,const AuthoredGovernanceAgencyCommand& command){auto common=command_common_guard(w,actor,political_governance_agency_command_kind(command.command));if(!common.ok)return common;auto id=policy_id(w,actor);if(!id.ok)return {false,{},id.error};const auto* p=director_policy(w.director,*w.catalog->director,actor);if(command.origin.actor_id!=actor||command.origin.director_policy_id!=id.value||!p||p->governance_agency_intent_id!=std::optional<StableId>{command.origin.intent_id})return common_failure("GovernanceAgencyIntentOriginMismatch",actor);return validate_political_governance_agency_authored_origin(*w.catalog->director->governance_agency_intents,command.origin,actor,political_governance_agency_command_kind(command.command));}
}
Outcome<std::optional<DecisionProposal>> propose_political_governance_agency_director_world(const WorldBundle& w,const KnownSubjectView& known,const DirectorPolicy& policy,const DecisionProposal& base){auto id=policy_id(w,known.actor_id);if(!id.ok)return id.error.kind==ErrorKind::rule?Outcome<std::optional<DecisionProposal>>{true,std::nullopt,{}}:Outcome<std::optional<DecisionProposal>>{false,{},id.error};if(!w.catalog->travel||!policy.governance_agency_intent_id)return {false,{},common_failure("GovernanceAgencyIntentWorldProfileRequired").error};const auto* i=w.catalog->director->governance_agency_intents->intents.find(*policy.governance_agency_intent_id);if(!i)return {false,{},common_failure("GovernanceAgencyIntentSourceMismatch").error};auto holder=PoliticalGovernanceAgencyWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};if(!holder.value)return {false,{},common_failure("GovernanceAgencyIntentVersionPairRequired").error};auto governance=w.governance_read();PoliticalGovernanceAgencyIntentAccess read(holder.value->context(),governance,id.value);PoliticalGovernanceAgencyDirectorContext context{w.common,*w.catalog->travel,*w.catalog->politics,*w.catalog->political_governance_agencies,read,id.value};return propose_director_governance_agency(context,known,policy,*i,base,w.catalog->director->candidates_per_subject);}
// 仅原完整控制/Agency/Governance/Task之后调用；未选择2版仍严格拒漂浮17号计划。
Status validate_political_governance_agency_director_world(const WorldBundle& w){if(!w.catalog->director)return common_success();const bool enabled=bool(w.catalog->director->governance_agency_intents);auto selected=political_governance_agency_selected_version(w.catalog->identity.module_versions);if(!selected.ok)return {false,{},selected.error};if(enabled!=(selected.value==2))return common_failure("GovernanceAgencyIntentVersionPairRequired");if(!enabled)return validate_political_governance_agency_intent_director(*w.catalog->director,w.director,nullptr,nullptr);auto holder=PoliticalGovernanceAgencyWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};if(!holder.value)return common_failure("GovernanceAgencyIntentVersionPairRequired");auto governance=w.governance_read();return validate_political_governance_agency_intent_director(*w.catalog->director,w.director,&holder.value->context(),&governance);}
Outcome<PoliticalGovernanceAgencyQuote> prepare_authored_governance_agency_world(const WorldBundle& w,const StableId& actor,const AuthoredGovernanceAgencyCommand& command){auto valid=guard(w,actor,command);if(!valid.ok)return {false,{},valid.error};auto holder=PoliticalGovernanceAgencyWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};if(!holder.value)return {false,{},common_failure("GovernanceAgencyIntentVersionPairRequired").error};auto rules=holder.value->context().rules;rules.authored_command=&command.origin;PoliticalGovernanceAgencyBusinessContext context{rules,holder.value->context().relief_catalog,holder.value->context().result_match};return preview_political_governance_agency_business(context,actor,command.command);}
// 两原NPC保存集持有Common/Agency/Governance；晚失败由同一外层候选撤回，永久来源不冒玩家结果。
Outcome<PoliticsEffects> commit_authored_governance_agency_world(WorldBundle& w,const StableId& actor,const AuthoredGovernanceAgencyCommand& command,const PoliticalGovernanceAgencyQuote& quote){auto valid=guard(w,actor,command);if(!valid.ok)return {false,{},valid.error};auto holder=PoliticalGovernanceAgencyWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};if(!holder.value)return {false,{},common_failure("GovernanceAgencyIntentVersionPairRequired").error};auto rules=holder.value->context().rules;rules.authored_command=&command.origin;PoliticalGovernanceAgencyBusinessContext context{rules,holder.value->context().relief_catalog,holder.value->context().result_match};auto id=apply_political_governance_agency_business_in_candidate(w.common,w.politics_governance,*w.political_governance_agencies,context,actor,command.command,quote);if(!id.ok)return {false,{},id.error};std::vector<StableId> authorities;if(const auto* issue=w.political_governance_agencies->issues.find(id.value))authorities.push_back(issue->authority_fact_id);return {true,{{},{id.value},std::move(authorities)},{}};}
}
